function setUIMode(mode){plus.mode=mode==='advanced'?'advanced':'simple';document.body.dataset.mode=plus.mode;$('uiMode').value=plus.mode;try{localStorage.setItem('studio-mode',plus.mode)}catch{}if(plus.mode==='simple'&&advancedTools.includes(tool))setTool('select');requestAnimationFrame(()=>{if(image)fit()})}
