setTool=(function(previous){return function(value){if(advancedTools.includes(value)&&plus.mode==='simple')setUIMode('advanced');previous(value)}})(setTool);
function extraReady(){const ready=!!image;for(const id of ['readMode','saveVersion','publicationOpen','checkExport','insertStamp'])$(id).disabled=!ready;const selectedItems=[...studio.selection].map(i=>items[i]).filter(Boolean),arrows=selectedItems.filter(o=>o.type==='arrow'),targets=selectedItems.filter(o=>['text','step','magnify'].includes(o.type));$('linkArrow').disabled=arrows.length!==1||targets.length!==1||selectedItems.length!==2||arrows[0].locked;$('unlinkArrow').disabled=!arrows.some(o=>o.linkTo&&!o.locked)}
update=function(){plusBase.update();extraReady()};
function publicationJSON(){return {...plus.publication}}
projectData=function(){const data=plusBase.projectData();data.publication=publicationJSON();return data};
function validatePublication(p){if(p===undefined)return{cover:false,title:'',unit:'',date:'',version:'',header:'',footer:'',logo:''};if(!p||typeof p.cover!=='boolean')throw Error('文件設定格式不正確');for(const k of ['title','unit','date','version','header','footer'])if(typeof p[k]!=='string'||p[k].length>300)throw Error('文件文字格式不正確');if(typeof p.logo!=='string'||p.logo.length>4000000||(p.logo&&!/^data:image\/png;base64,[A-Za-z0-9+/=\r\n]+$/.test(p.logo)))throw Error('Logo 格式不正確');return {...p}}
decodeProject=async function(data){const pub=validatePublication(data?.publication);const doc=await plusBase.decodeProject(data);let logoImage=null;if(pub.logo){logoImage=new Image();logoImage.src=pub.logo;await logoImage.decode();if(logoImage.width>2048||logoImage.height>2048)throw Error('Logo 尺寸過大')}for(const p of doc.pages){const ids=new Set();for(const o of p.items){if(typeof o.id!=='string'||ids.has(o.id))throw Error('標註識別碼重複');ids.add(o.id);if(o.stamp!==undefined&&(typeof o.stamp!=='boolean'||(o.stamp&&o.type!=='text')))throw Error('圖章格式不正確');if(o.linkTo!==undefined&&(o.type!=='arrow'||typeof o.linkTo!=='string'||!o.linkTip||!Number.isFinite(o.linkTip.x)||!Number.isFinite(o.linkTip.y)||Math.abs(o.linkTip.x)>64000||Math.abs(o.linkTip.y)>64000))throw Error('箭頭連動格式不正確')}}doc.publication=pub;doc.logoImage=logoImage;return doc};
installDocument=function(doc){plus.publication=doc.publication||validatePublication();plus.logoImage=doc.logoImage||null;plusBase.installDocument(doc)};


// Version snapshots use the same local IndexedDB as drafts, under a separate key.
async function versionStore(value){const db=await draftDB();return new Promise((resolve,reject)=>{const tx=db.transaction('drafts',value===undefined?'readonly':'readwrite'),s=tx.objectStore('drafts'),r=value===undefined?s.get('versions'):s.put(value,'versions');tx.oncomplete=()=>{db.close();resolve(r.result)};tx.onerror=()=>{db.close();reject(tx.error)};tx.onabort=()=>{db.close();reject(tx.error||Error('版本儲存中止'))}})}
async function loadVersions(){if(!plus.historyReady){plus.history=await versionStore()||[];plus.historyReady=true}return plus.history}
function saveHistory(label='自動保存',force=false){if(!image)return Promise.resolve(false);const data=projectData(),fingerprint=JSON.stringify(data);const task=async()=>{try{await loadVersions();if(!force&&fingerprint===plus.historyFingerprint)return true;if(!force&&Date.now()-plus.lastHistoryAt<60000){clearTimeout(versionTimer);versionTimer=setTimeout(()=>saveHistory(),60100-(Date.now()-plus.lastHistoryAt));return true}const entry={id:uid(),at:Date.now(),label:label.slice(0,80),document:data};let next=[entry,...plus.history].slice(0,10);while(next.length>1&&JSON.stringify(next).length>80*1024*1024)next.pop();if(JSON.stringify(next).length>80*1024*1024)throw Error('此專案超過版本容量，請下載專案備份');await versionStore(next);plus.history=next;plus.historyFingerprint=fingerprint;plus.lastHistoryAt=Date.now();$('versionStatus').textContent='版本已保存 '+new Date().toLocaleTimeString('zh-TW');renderVersions();return true}catch(e){$('versionStatus').textContent='版本未保存：'+e.message;$('versionsStatus').textContent=$('versionStatus').textContent;return false}};plus.historyChain=plus.historyChain.then(task,task);return plus.historyChain}
let versionTimer;
scheduleDraft=function(){plusBase.scheduleDraft();clearTimeout(versionTimer);if(image&&!studio.restoring)versionTimer=setTimeout(()=>saveHistory(),1800)};
function renderVersions(){const list=$('versionsList');list.replaceChildren();for(const entry of plus.history){const li=document.createElement('li'),label=document.createElement('span'),b=document.createElement('button');label.textContent=entry.label+' · '+new Date(entry.at).toLocaleString('zh-TW')+' · '+(entry.document.pages?.length||1)+' 頁';b.textContent='還原';b.onclick=async()=>{b.disabled=true;try{const doc=await decodeProject(entry.document);if(image&&!await saveHistory('還原前備份',true)){toast('無法備份目前專案，請先下載專案');return}installDocument(doc);scheduleDraft();$('versionsDialog').close();toast('已還原版本')}catch(e){toast(e.message)}finally{b.disabled=false}};li.append(label,b);list.append(li)}$('versionsStatus').textContent=plus.history.length?'共 '+plus.history.length+' 份版本':'尚無版本，可先儲存目前專案'}
$('versionsOpen').onclick=async()=>{$('versionsDialog').showModal();try{await loadVersions();renderVersions()}catch(e){$('versionsStatus').textContent='無法讀取版本：'+e.message}};
$('saveVersion').onclick=async()=>{if(await saveHistory('手動保存',true))toast('已保存歷史版本')};
$('saveNamedVersion').onclick=async()=>{if(await saveHistory($('versionName').value.trim()||'手動保存',true)){$('versionName').value='';toast('已保存歷史版本')}};
const oldDeletePage=$('deletePage').onclick;
$('deletePage').onclick=async()=>{if(!image)return;if(!await saveHistory('刪頁前備份',true)){toast('版本未保存，請先下載專案備份');return}oldDeletePage()};
$('replacePage').onclick=()=>$('replaceFilePlus').click();
$('replaceFilePlus').onchange=async e=>{const file=e.target.files[0];e.target.value='';if(!file||!image)return;let url;try{if(!/^image\/(png|jpeg|webp|gif)$/.test(file.type)||file.size>30*1024*1024)throw Error('請選擇 30 MB 以下的圖片');url=URL.createObjectURL(file);const img=new Image();img.src=url;await img.decode();if(img.width>16000||img.height>16000||img.width*img.height>32000000)throw Error('圖片尺寸過大');capturePage();if(studio.pages.reduce((n,p)=>n+(p===currentPage()?img.width*img.height:p.source.width*p.source.height),0)>100000000)throw Error('整份教學圖片總量過大');plus.replacing={img,name:file.name,id:currentPage().id};$('replaceSummary').textContent=sourceImage.width+' × '+sourceImage.height+' → '+img.width+' × '+img.height+' 像素；本頁 '+items.length+' 個標註。若畫面版面改變，套用後請檢查標註位置。';$('replaceStatus').textContent='';$('replaceDialog').showModal()}catch(e){toast(e.message)}finally{if(url)URL.revokeObjectURL(url)}};
$('replaceDialog').addEventListener('close',()=>{plus.replacing=null});
$('confirmReplace').onclick=async()=>{const r=plus.replacing;if(!r||currentPage()?.id!==r.id)return;const b=$('confirmReplace');b.disabled=true;try{capturePage();const old=currentPage(),mode=document.querySelector('[name=replaceMode]:checked').value,p=makePage(r.img,r.name);p.title=old.title;p.id=old.id;if(mode!=='clear'){p.items=clone(old.items);p.margins={...old.margins};p.nextNumber=old.nextNumber;const sx=r.img.width/old.source.width,sy=r.img.height/old.source.height,scale=Math.sqrt(sx*sy);p.crop=old.crop?{...old.crop}:null;if(mode==='scale'){if(p.crop){p.crop.x=Math.floor(p.crop.x*sx);p.crop.y=Math.floor(p.crop.y*sy);p.crop.w=Math.max(1,Math.min(r.img.width-p.crop.x,Math.round(old.crop.w*sx)));p.crop.h=Math.max(1,Math.min(r.img.height-p.crop.y,Math.round(old.crop.h*sy)))}for(const o of p.items){o.x=p.margins.left+(o.x-p.margins.left)*sx;o.y=p.margins.top+(o.y-p.margins.top)*sy;o.w*=sx;o.h*=sy;o.size=Math.max(16,Math.min(160,o.size*scale));o.width=Math.max(2,Math.min(24,o.width*scale));if(o.type==='step')o.w=Math.max(160,Math.min(1600,o.w));if(o.type==='magnify'){o.sx=p.margins.left+(o.sx-p.margins.left)*sx;o.sy=p.margins.top+(o.sy-p.margins.top)*sy;o.sw*=sx;o.sh*=sy}if(o.linkTip){o.linkTip.x=p.margins.left+(o.linkTip.x-p.margins.left)*sx;o.linkTip.y=p.margins.top+(o.linkTip.y-p.margins.top)*sy}}}else if(p.crop&&(p.crop.x+p.crop.w>r.img.width||p.crop.y+p.crop.h>r.img.height)){for(const o of p.items){o.x+=p.crop.x;o.y+=p.crop.y;if(o.linkTip){o.linkTip.x+=p.crop.x;o.linkTip.y+=p.crop.y}if(o.type==='magnify'){o.sx+=p.crop.x;o.sy+=p.crop.y}}p.crop=null}p.history=[JSON.stringify({items:p.items,margins:p.margins,crop:p.crop})];p.historyIndex=0}paddedImage(croppedBase(p.source,p.crop),p.margins);if(!await saveHistory('換圖前備份',true))throw Error('無法保存舊版本，請先下載專案備份');studio.pages[studio.active]=p;activatePage(studio.active,false);studio.revision++;scheduleDraft();$('replaceDialog').close();toast('已替換截圖，舊圖片保存在歷史版本')}catch(e){$('replaceStatus').textContent=e.message}finally{b.disabled=false}};
// Linked arrows point at a fixed image position while their start follows a target box.
function syncLinks(list){for(const o of list){if(!o.linkTo)continue;const target=list.find(t=>t.id===o.linkTo&&['step','text','magnify'].includes(t.type));if(!target){delete o.linkTo;delete o.linkTip;continue}const b=bounds(target),cx=b.x+b.w/2,cy=b.y+b.h/2,dx=o.linkTip.x-cx,dy=o.linkTip.y-cy,t=Math.min(dx?b.w/2/Math.abs(dx):Infinity,dy?b.h/2/Math.abs(dy):Infinity);o.x=cx+dx*(Number.isFinite(t)?Math.min(t,1):0);o.y=cy+dy*(Number.isFinite(t)?Math.min(t,1):0);o.w=o.linkTip.x-o.x;o.h=o.linkTip.y-o.y}}
render=function(){syncLinks(items);plusBase.render()};
paintAnnotations=function(c){syncLinks(items);plusBase.paintAnnotations(c)};
commit=function(){syncLinks(items);plusBase.commit()};
shiftObjects=function(dx,dy){plusBase.shiftObjects(dx,dy);for(const o of items)if(o.linkTip){o.linkTip.x+=dx;o.linkTip.y+=dy}};
$('linkArrow').onclick=()=>{const list=[...studio.selection].map(i=>items[i]),a=list.find(o=>o.type==='arrow'),t=list.find(o=>['step','text','magnify'].includes(o.type));if(!a||!t||a.locked)return;a.linkTo=t.id;a.linkTip={x:a.x+a.w,y:a.y+a.h};commit();toast('箭頭起點會跟隨說明框，箭頭尖端固定；可解除連動再移動')};
$('unlinkArrow').onclick=()=>{for(const i of studio.selection)if(!items[i].locked){delete items[i].linkTo;delete items[i].linkTip}commit()};
$('duplicate').onclick=()=>{const originals=[...studio.selection].map(i=>items[i]),map=new Map(originals.map(o=>[o.id,uid()])),copies=originals.map(o=>{const n={...clone(o),id:map.get(o.id),x:o.x+24,y:o.y+24,locked:false};if(n.linkTip){n.linkTip.x+=24;n.linkTip.y+=24;if(map.has(n.linkTo))n.linkTo=map.get(n.linkTo);else{delete n.linkTo;delete n.linkTip}}return n}),start=items.length;items.push(...copies);setSelection(copies.map((_,i)=>start+i));commit()};
bounds=function(o){const b=plusBase.bounds(o);return o.stamp?{x:b.x-o.size*.3,y:b.y-o.size*.2,w:b.w+o.size*.6,h:b.h+o.size*.4}:b};
drawObject=function(c,o){if(!o.stamp)return plusBase.drawObject(c,o);const b=bounds(o);c.save();c.fillStyle=o.color;c.beginPath();c.roundRect(b.x,b.y,b.w,b.h,Math.min(12,o.size*.2));c.fill();const rgb=o.color.slice(1).match(/../g).map(x=>parseInt(x,16)),lum=.2126*rgb[0]+.7152*rgb[1]+.0722*rgb[2];plusBase.drawObject(c,{...o,stamp:false,color:lum>160?'#172033':'#ffffff'});c.restore()};
let phrases=[];try{const v=JSON.parse(localStorage.getItem('studio-phrases')||'[]');if(Array.isArray(v))phrases=v.filter(s=>typeof s==='string'&&s.length<=500).slice(0,20)}catch{}
function renderPhrases(){while($('phraseSelect').options.length>5)$('phraseSelect').remove(5);for(const phrase of phrases){const o=document.createElement('option');o.textContent=phrase;$('phraseSelect').append(o)}}renderPhrases();
$('rememberPhrase').onclick=()=>{const t=$('textInput').value.trim();if(!t||t.length>500){toast('請先輸入 1–500 字的說明');return}phrases=[t,...phrases.filter(p=>p!==t)].slice(0,20);try{localStorage.setItem('studio-phrases',JSON.stringify(phrases));renderPhrases();toast('已記住常用說明')}catch{toast('瀏覽器無法儲存常用說明')}};
