// Publication settings are staged until the user presses Save.
let stagedLogo='',stagedLogoImage=null;
$('publicationOpen').onclick=()=>{for(const k of ['title','unit','date','version','header','footer'])$('pub'+k[0].toUpperCase()+k.slice(1)).value=plus.publication[k];$('pubCover').checked=plus.publication.cover;stagedLogo=plus.publication.logo;stagedLogoImage=plus.logoImage;showLogo();$('publicationStatus').textContent='';$('publicationDialog').showModal()};
function showLogo(){$('logoPreview').hidden=!stagedLogo;if(stagedLogo)$('logoPreview').src=stagedLogo;else $('logoPreview').removeAttribute('src')}
$('chooseLogo').onclick=()=>$('logoFile').click();
$('clearLogo').onclick=()=>{stagedLogo='';stagedLogoImage=null;showLogo()};
$('logoFile').onchange=async e=>{const f=e.target.files[0];e.target.value='';if(!f)return;let url;try{if(f.size>10000000||!/^image\/(png|jpeg|webp)$/.test(f.type))throw Error('請選擇 10 MB 以下的 PNG、JPG 或 WebP');url=URL.createObjectURL(f);const img=new Image();img.src=url;await img.decode();if(img.width*img.height>32000000)throw Error('Logo 尺寸過大');const s=Math.min(1,640/img.width,320/img.height),c=document.createElement('canvas');c.width=Math.max(1,Math.round(img.width*s));c.height=Math.max(1,Math.round(img.height*s));c.getContext('2d').drawImage(img,0,0,c.width,c.height);stagedLogo=c.toDataURL();stagedLogoImage=c;showLogo();$('publicationStatus').textContent='Logo 已準備，按儲存套用'}catch(e){$('publicationStatus').textContent=e.message}finally{if(url)URL.revokeObjectURL(url)}};
$('savePublication').onclick=()=>{const p={cover:$('pubCover').checked,logo:stagedLogo};for(const k of ['title','unit','date','version','header','footer'])p[k]=$('pub'+k[0].toUpperCase()+k.slice(1)).value.trim();plus.publication=validatePublication(p);plus.logoImage=stagedLogoImage;studio.revision++;scheduleDraft();$('publicationDialog').close();toast('已儲存文件設定')};
const previousAcceptImage=acceptImage;
acceptImage=function(img,name){const result=previousAcceptImage(img,name);if(result){plus.publication=validatePublication();plus.logoImage=null}return result};
function textLines(g,text,maxWidth){const lines=[];for(const para of String(text).split('\n')){let line='';for(const ch of para){if(line&&g.measureText(line+ch).width>maxWidth){lines.push(line);line=ch}else line+=ch}lines.push(line)}return lines}
function coverCanvas(pub,logo,width=1200){const c=document.createElement('canvas');c.width=width;c.height=Math.round(width*1.4142);const g=c.getContext('2d'),u=width/1200;g.scale(u,u);g.fillStyle='#f1f5fb';g.fillRect(0,0,1200,1697);g.fillStyle='#2563eb';g.fillRect(80,250,12,300);g.fillStyle='#172d50';g.font='700 62px "Microsoft JhengHei",sans-serif';const title=textLines(g,pub.title||'操作教學',960);title.forEach((t,i)=>g.fillText(t,120,360+i*90));g.fillStyle='#4b607b';g.font='32px "Microsoft JhengHei",sans-serif';let y=Math.max(850,430+title.length*90);for(const value of [pub.unit,pub.date,pub.version])if(value){for(const line of textLines(g,value,960)){g.fillText(line,120,y);y+=48}y+=18}if(logo){const s=Math.min(320/logo.width,140/logo.height);g.drawImage(logo,120,100,logo.width*s,logo.height*s)}g.fillStyle='#2563eb';g.fillRect(120,1510,960,3);g.font='22px "Microsoft JhengHei",sans-serif';g.fillStyle='#607089';g.fillText(pub.footer||'操作步驟與圖解說明',120,1560,960);return c}
function bandCanvas(text,leftLogo,width=1200,height=64){const c=document.createElement('canvas');c.width=width;c.height=height;const g=c.getContext('2d');g.fillStyle='#fff';g.fillRect(0,0,width,height);let x=20;if(leftLogo){const s=Math.min(100/leftLogo.width,(height-12)/leftLogo.height);g.drawImage(leftLogo,12,6,leftLogo.width*s,leftLogo.height*s);x=125}let size=Math.min(28,height*.48);g.fillStyle='#41536d';g.textBaseline='middle';g.font=size+'px "Microsoft JhengHei",sans-serif';while(size>12&&g.measureText(text).width>width-x-20){size--;g.font=size+'px "Microsoft JhengHei",sans-serif'}g.fillText(text,x,height/2,width-x-20);return c}
function publicationPage(p,i,total,pub,logo){const body=pageCanvas(p),c=document.createElement('canvas');const top=pub.header||logo?112:64,bottom=pub.footer?54:0;c.width=body.width;c.height=body.height+top+bottom;const g=c.getContext('2d');g.fillStyle='#fff';g.fillRect(0,0,c.width,c.height);let y=0;if(pub.header||logo){g.drawImage(bandCanvas(pub.header,logo),0,0,c.width,48);y=48}g.drawImage(titleCanvas((i+1)+'. '+p.title),0,y,c.width,64);g.drawImage(body,0,top);if(bottom)g.drawImage(bandCanvas(pub.footer+'　｜　'+(i+1)+' / '+total),0,top+body.height,c.width,bottom);return c}
buildPDF=async function(){capturePage();const pages=studio.pages.map(p=>({...p,items:clone(p.items),margins:{...p.margins},crop:p.crop?{...p.crop}:null})),pub=publicationJSON(),logo=plus.logoImage;await loadScript('vendor/pdf-lib.min.js');const pdf=await PDFLib.PDFDocument.create();let sheet=0;if(pub.cover){const c=coverCanvas(pub,logo),asset=await pdf.embedPng(await (await canvasBlob(c)).arrayBuffer());pdf.addPage([595.28,841.89]).drawImage(asset,{x:0,y:0,width:595.28,height:841.89})}const total=pages.reduce((n,p)=>{const cw=(p.crop?.w||p.source.width)+p.margins.left+p.margins.right,ch=(p.crop?.h||p.source.height)+p.margins.top+p.margins.bottom;return n+Math.ceil(ch/Math.max(1,Math.floor(680/(523/cw))))},0);for(let i=0;i<pages.length;i++){const p=pages[i],c=pageCanvas(p),ratio=523/c.width,slice=Math.max(1,Math.floor(680/ratio)),title=await pdf.embedPng(await (await canvasBlob(titleCanvas((i+1)+'. '+p.title))).arrayBuffer()),header=pub.header||logo?await pdf.embedPng(await (await canvasBlob(bandCanvas(pub.header,logo))).arrayBuffer()):null;for(let y=0;y<c.height;y+=slice){const h=Math.min(slice,c.height-y),tile=document.createElement('canvas');tile.width=c.width;tile.height=h;tile.getContext('2d').drawImage(c,0,y,c.width,h,0,0,c.width,h);const asset=await pdf.embedPng(await (await canvasBlob(tile)).arrayBuffer()),footer=await pdf.embedPng(await (await canvasBlob(bandCanvas((pub.footer?pub.footer+'　｜　':'')+(++sheet)+' / '+total))).arrayBuffer()),page=pdf.addPage([595.28,841.89]);if(header)page.drawImage(header,{x:36,y:800,width:523,height:28});page.drawImage(title,{x:36,y:762,width:523,height:35});page.drawImage(asset,{x:36,y:746-h*ratio,width:523,height:h*ratio});page.drawImage(footer,{x:36,y:18,width:523,height:28});tile.width=tile.height=1}$('bookStatus').textContent='正在匯出 '+(i+1)+' / '+pages.length+' 頁…';await new Promise(r=>setTimeout(r,0));c.width=c.height=1}return pdf.save()};
$('downloadLong').onclick=async()=>{try{capturePage();const w=Number($('bookWidth').value),gap=Number($('bookGap').value),pub=publicationJSON(),logo=plus.logoImage;if(!Number.isInteger(w)||w<200||w>4000||!Number.isInteger(gap)||gap<0||gap>500)throw Error('寬度需為 200–4000，間距需為 0–500');const dims=studio.pages.map(p=>{const width=(p.crop?.w||p.source.width)+p.margins.left+p.margins.right,height=(p.crop?.h||p.source.height)+p.margins.top+p.margins.bottom+(pub.header||logo?112:64)+(pub.footer?54:0);return{w:width,h:height,s:Math.min(1,w/width)}});const coverH=pub.cover?Math.round(w*1.4142)+gap:0,h=coverH+dims.reduce((n,d)=>n+Math.round(d.h*d.s),0)+Math.max(0,dims.length-1)*gap;if(h>16000||h*w>32000000)throw Error('長圖過大，請縮小寬度或改用 PDF');const c=document.createElement('canvas');c.width=w;c.height=h;const g=c.getContext('2d');g.fillStyle='#fff';g.fillRect(0,0,w,h);let y=0;if(pub.cover){const cover=coverCanvas(pub,logo,w);g.drawImage(cover,0,0);y=coverH}studio.pages.forEach((p,i)=>{const part=publicationPage(p,i,studio.pages.length,pub,logo),d=dims[i],dw=Math.round(d.w*d.s),dh=Math.round(d.h*d.s);g.drawImage(part,(w-dw)/2,y,dw,dh);y+=dh+gap});downloadBlob(await canvasBlob(c),'教學長圖.png');$('bookStatus').textContent='含文件設定的長圖已下載'}catch(e){$('bookStatus').textContent=e.message}};
// Checks are advisory: users can return to the specific annotation or continue.
function inspectExport(all=true,pdf=false){capturePage();const issues=[];const indices=all?studio.pages.map((_,i)=>i):[studio.active];for(const pi of indices){const p=studio.pages[pi],w=(p.crop?.w||p.source.width)+p.margins.left+p.margins.right,h=(p.crop?.h||p.source.height)+p.margins.top+p.margins.bottom,seen=new Map(),texts=[];syncLinks(p.items);p.items.forEach((o,i)=>{const b=bounds(o),add=msg=>{if(issues.length<200)issues.push({page:pi,item:i,message:msg})};if(b.x<-.5||b.y<-.5||b.x+b.w>w+.5||b.y+b.h>h+.5)add('標註超出圖片邊界');if(['text','step','number'].includes(o.type)&&(o.size<20||(pdf&&o.size*523/w<9)))add(pdf?'文字在 A4 PDF 可能過小':'文字小於 20 px，可能不易閱讀');if(['step','number'].includes(o.type)){if(seen.has(o.n))add('步驟編號 '+o.n+' 重複');seen.set(o.n,i)}if(['text','step'].includes(o.type))texts.push({i,b});});for(let a=0;a<texts.length&&issues.length<200;a++)for(let b=a+1;b<texts.length&&issues.length<200;b++){const x=texts[a].b,y=texts[b].b,iw=Math.min(x.x+x.w,y.x+y.w)-Math.max(x.x,y.x),ih=Math.min(x.y+x.h,y.y+y.h)-Math.max(x.y,y.y);if(iw>4&&ih>4&&iw*ih>Math.min(x.w*x.h,y.w*y.h)*.08)issues.push({page:pi,item:texts[b].i,message:'說明文字與另一個說明框重疊'})}}return issues}
function showChecks(issues,action){plus.pendingExport=action||null;$('checkList').replaceChildren();$('checkSummary').textContent=issues.length?'發現 '+issues.length+(issues.length===200?' 筆以上':' 筆')+' 可檢查項目，可定位修改或仍要匯出。':'未發現標註邊界、文字大小、重疊或編號問題。';for(const issue of issues){const li=document.createElement('li'),text=document.createElement('span'),button=document.createElement('button');text.textContent='第 '+(issue.page+1)+' 頁：'+issue.message;button.textContent='定位';button.onclick=()=>{$('checkDialog').close();if($('bookDialog').open)$('bookDialog').close();activatePage(issue.page);setTool('select');setSelection([issue.item]);fit()};li.append(text,button);$('checkList').append(li)}$('continueExport').hidden=!action;$('checkDialog').showModal()}
$('checkExport').onclick=()=>showChecks(inspectExport(true,false));
$('continueExport').onclick=()=>{const action=plus.pendingExport;plus.pendingExport=null;$('checkDialog').close();if(action)action()};
$('checkDialog').addEventListener('close',()=>plus.pendingExport=null);
for(const id of ['export','copyImage','downloadLong','downloadPDF']){const action=$(id).onclick;$(id).onclick=()=>{try{const issues=inspectExport(id==='downloadLong'||id==='downloadPDF',id==='downloadPDF');if(issues.length)showChecks(issues,action);else action()}catch(e){toast(e.message)}}}
// Reader renders flattened images; it never switches or edits the active editor page.
let readerEntries=[];
function buildReader(){capturePage();readerEntries=[];if(plus.publication.cover)readerEntries.push({cover:true});studio.pages.forEach((p,pi)=>{const steps=p.items.map((o,i)=>({o,i})).filter(v=>['step','number'].includes(v.o.type)).sort((a,b)=>a.o.n-b.o.n);if(steps.length)steps.forEach(s=>readerEntries.push({page:pi,item:s.i}));else readerEntries.push({page:pi,item:-1})});plus.readerStep=0}
function renderReader(){const entry=readerEntries[plus.readerStep];if(!entry)return;const pub=plus.publication;let c;if(entry.cover){c=coverCanvas(pub,plus.logoImage,900);$('readerTitle').textContent=pub.title||'操作教學';$('readerCaption').textContent=[pub.unit,pub.date,pub.version].filter(Boolean).join(' · ')}else{const p=studio.pages[entry.page];c=publicationPage(p,entry.page,studio.pages.length,pub,plus.logoImage);$('readerTitle').textContent=p.title||'操作教學';const o=p.items[entry.item];$('readerCaption').textContent=o?'步驟 '+o.n+(o.text?'：'+o.text:''):'閱讀本頁教學';if(o){const b=bounds(o),g=c.getContext('2d'),top=pub.header||plus.logoImage?112:64;g.strokeStyle='#2563eb';g.lineWidth=4;g.setLineDash([10,6]);g.strokeRect(b.x-6,b.y+top-6,b.w+12,b.h+12)}}$('readerImage').src=c.toDataURL();$('readerProgress').textContent=(plus.readerStep+1)+' / '+readerEntries.length+(!entry.cover?' · 第 '+(entry.page+1)+' 頁':' · 封面');$('readerPrev').disabled=plus.readerStep===0;$('readerNext').disabled=plus.readerStep===readerEntries.length-1}
$('readMode').onclick=()=>{buildReader();renderReader();$('readerDialog').showModal()};
$('readerPrev').onclick=()=>{if(plus.readerStep>0){plus.readerStep--;renderReader()}};
$('readerNext').onclick=()=>{if(plus.readerStep<readerEntries.length-1){plus.readerStep++;renderReader()}};
$('readerDialog').addEventListener('keydown',e=>{if(e.key==='ArrowLeft'||e.key==='ArrowRight'){e.preventDefault();e.stopPropagation();$(e.key==='ArrowLeft'?'readerPrev':'readerNext').click()}},true);
extraReady();

